// Обработчик отправки и сериализации данных формы
studentForm.addEventListener('submit', function(e) {
  e.preventDefault();
  const isNoValidate = e.submitter && e.submitter.hasAttribute('formnovalidate');

  const formData = new FormData(this);
  const dataObj = {};
  const languages = [];

  for (let [key, val] of formData.entries()) {
    if (key === 'languages') languages.push(val);
    else dataObj[key] = val;
  }
  dataObj['languages'] = languages;

  // Сериализация в application/x-www-form-urlencoded
  const urlParams = new URLSearchParams(formData);
  rawPayload.textContent = urlParams.toString();

  // Сериализация в JSON
  jsonPayload.textContent = JSON.stringify(dataObj, null, 2);
  resultSection.style.display = 'block';
});
